UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 Nodo nuevo — doctrina de desarrollo de cuenta (CAMPO, Emilio). El espejo tiene seis estados y cada uno ensena una regla: atacar cierra, solo precio no mueve, consolidacion abre, pedir que pruebe asusta, conviccion con razon convence, garantizar desconfia.", "scope": {"skills_in_focus": ["presentation.consolidacion_proveedor", "presentation.beneficio_no_caracteristica"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Tres cosas que mirar, y las tres van contra el instinto.\n\nNo digo una sola palabra en contra del otro proveedor.\n\nNo vendo el producto: vendo un proveedor menos que seguir.\n\nY no le pido que pruebe. Le doy mi conviccion con la razon detras, y ahi me callo.", "first_message": "Ah, mire, eso lo maneja con otro. Que bueno que lo tenga cubierto.\n\nNosotros tambien lo traemos, de las mismas marcas que ya le surtimos.\n\nY le va a servir por algo mas que el precio: en lugar de estar esperando dos entregas de dos proveedores distintos, le llega todo junto en la misma visita. Menos pedidos que seguir, menos gente a quien marcarle.\n\nYo no le puedo garantizar nada, pero estoy seguro de que se le va a mover — se lo digo porque en los negocios de por aca es de lo que mas sale."}, "you_do": {"prompt": "REGLA NUMERO CERO: eres un cliente CONTENTO con su proveedor actual. No tienes quejas de el y no las vas a inventar. Si el vendedor te pregunta si te falla, contestas con sinceridad que no.\n\nEres el dueno de un negocio que ya le compra a este vendedor algunas familias. Adopta el tipo de negocio y las familias del contexto de la empresa. HAY UNA FAMILIA que le compras a OTRO proveedor desde hace anos, sin ningun problema, y ya se lo dijiste.\n\nCOMO REACCIONAS:\n\nSI ATACA AL OTRO PROVEEDOR o insinua que te esta fallando, que te cobra caro o que no te conviene: te pones a la defensiva y DEFIENDES tu decision, porque criticarlo es criticarte a ti por haberlo elegido. A partir de ahi te cierras y ya no te interesa.\n\nSI TE OFRECE SOLO PRECIO o solo el producto: contestas que ya lo tienes cubierto y no ves razon para cambiar. Tu interes no se mueve.\n\nSI TE HABLA DE CONSOLIDAR (menos proveedores, todo en una entrega, menos pedidos que seguir): ahi si te interesa de verdad y preguntas mas, porque es un problema real que tienes y no habias pensado en resolverlo.\n\nSI TE PIDE QUE LO PRUEBES (pongale unas pocas para que pruebe, para que vea si le funciona): te da desconfianza y te echas para atras. Probar significa riesgo y no tienes ninguna razon para arriesgarte con algo que ya tienes resuelto.\n\nSI TE DA CONVICCION CON RAZON (no le garantizo nada pero estoy seguro, porque en negocios como el suyo es de lo que mas sale): te da confianza y avanzas.\n\nSI TE GARANTIZA que se va a vender o que no va a fallar: desconfias, porque nadie puede garantizar eso y suena a vendedor.\n\nResponde en 1 o 2 frases, natural.", "objective": "El vendedor presenta la familia que el cliente compra con otro proveedor sin atacarlo, usando el argumento de consolidacion, y cierra el argumento con conviccion respaldada por una razon — sin garantizar y sin pedir que pruebe. El scope se cubre cuando el cliente muestra interes real y pregunta mas."}, "closing": {"message": "Eso es presentar un hueco. No atacaste a nadie, vendiste un proveedor menos que seguir, y cerraste con conviccion en lugar de pedirle permiso para experimentar. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como cayo esa propuesta."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "ataca_al_proveedor", "severity": "critical", "description": "Critica, minimiza o insinua algo negativo del proveedor actual. Si el cliente lleva anos con el, criticarlo es criticar su decision, y la gente defiende sus decisiones. Cierra la puerta de inmediato.", "regla_id": "present.ataca_proveedor"}, {"id": "pide_que_pruebe", "severity": "major", "description": "Le pide al cliente que pruebe el producto para ver si le funciona. Le pasa el riesgo a el, y la gente no quiere experimentar con algo que ya tiene resuelto.", "regla_id": "present.pide_que_pruebe"}, {"id": "garantiza", "severity": "critical", "description": "Garantiza que el producto se va a vender o que no va a fallar. Es una promesa que no controla, y suena a vendedor. La conviccion sirve; la garantia destruye.", "regla_id": "present.garantiza", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}, {"id": "solo_precio", "severity": "major", "description": "Compite unicamente por precio o por caracteristicas del producto. Contra un proveedor establecido eso no alcanza: el cliente ya tiene eso cubierto.", "regla_id": "present.caracteristica_sin_traducir"}, {"id": "anuncia_plan_b", "severity": "minor", "description": "Ofrece ajustarlo si no se mueve. Le mete una duda que no tenia y desmiente la conviccion que acaba de afirmar.", "regla_id": "present.plan_b", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}], "success_criteria": [{"id": "presentation.consolidacion_proveedor", "weight": 0.6, "description": "Usa el argumento de consolidacion — menos proveedores que seguir, todo en una entrega, un solo contacto — en lugar de competir por precio o por producto. Y cierra con CONVICCION RESPALDADA: afirma que se va a mover Y da la razon por la que lo cree, sin garantizar nada. NO pide que lo pruebe: pedir que pruebe le pasa el riesgo al cliente y no se acredita.", "regla_id": "present.argumento_del_hueco"}, {"id": "presentation.beneficio_no_caracteristica", "weight": 0.4, "description": "Traduce la consolidacion a algo concreto que el cliente gana: menos tiempo, menos pedidos que rastrear, menos gente a quien marcarle. Mencionar que tambien manejan esa linea, sin traducirlo a un beneficio, no cumple.", "regla_id": "present.beneficio_no_caracteristica"}]}'::jsonb WHERE id = '4.15';
UPDATE public.nodes SET practice_script = '{"notes": "BOSS del Mundo 4 — el ciclo diagnóstico→presentación completo ante el arquetipo desconfiado d4. Integra M3 (capas, escucha) y M4 entero. El failure nuevo promesa_grandilocuente entrena la credibilidad: ante un desconfiado, la promesa grande es veneno — el valor se construye con anclas concretas. 18 turnos: la sesión más larga del mapa hasta ahora.", "scope": {"skills_in_focus": ["discovery.dolor_real", "presentation.conectar_dolor", "presentation.valor_personalizado", "presentation.pintar_imagenes", "presentation.tren_si_si", "relationship.cpr"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 18, "max_duration_seconds": 420, "min_turns_before_evaluation": 8}, "phases": {"you_do": {"prompt": "Eres el dueño de un negocio de perfil DESCONFIADO: varios vendedores te han prometido de más y cumplido de menos, así que recibes con escepticismo cordial — escuchas, pero no crees fácil. GUION: (1) Recibes la apertura con cortesía distante; NO sueltes bloqueo (ya te saludó bien) pero tu escepticismo se nota: a ver, dígame. (2) Tienes un DOLOR REAL (elige al azar: proveedor que te deja plantado quincenalmente / dinero muerto en producto parado / algo que piden y no consigues) — lo revelas por capas SOLO si te excavan la pista del aunque. (3) Tienes VIDA (elige 1 FORMD: nieto que ayuda / equipo de futbol / historia del local): si el vendedor la toca con genuinidad, tu escepticismo baja un escalón notable. (4) REGLA DE PRESENTACIÓN — tu desconfianza se derrite SOLO con evidencia conectada: si presenta nombrando TU dolor con TUS palabras, respondes interés cauto (¿y eso cómo estaría?); si pinta una escena de TU negocio resuelto, entras en ella con reserva pero entras; si sus preguntas de sí son genuinas, asientes; si suelta promesas grandes sin ancla (nunca le vamos a fallar, somos los mejores), tu desconfianza REGRESA: eso mismo me dijo el anterior. (5) Presentación genérica = te cierras: bueno, déjeme su tarjeta y yo le hablo. Tu techo: interesado-cauto que pide detalles concretos del siguiente paso — nunca eufórico. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor completa el ciclo con un cliente desconfiado: excava el dolor real por capas hasta la revelación y confirmación, construye conexión personal genuina en el camino (al menos un tema FORMD), y presenta CONECTADO: abre desde el dolor con las palabras del cliente, pinta al menos una escena de su negocio resuelto, siembra al menos dos síes genuinos, y traduce a beneficios concretos sin promesas grandilocuentes. El scope se cubre cuando el desconfiado muestra interés real: pregunta por detalles concretos del siguiente paso (cómo surtirían, cada cuánto, qué necesita hacer)."}, "closing": {"message": "Un desconfiado pidiéndote los detalles del siguiente paso — eso no se compra con promesas: se construye con valor. Acabas de recorrer el camino completo del diagnóstico a la presentación. El cierre te espera en el siguiente mundo. Vamos al desglose.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose y te digo donde estuvo la diferencia."}}, "version": "1.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "presentacion_generica", "severity": "critical", "description": "Presenta catálogo/calidad/años sin conectar con el dolor excavado — el desconfiado se cierra con un déjeme su tarjeta.", "regla_id": "present.dos_mitades", "severity_override": {"default": "major", "razon": "boss: escalada"}}, {"id": "promesa_grandilocuente", "severity": "major", "description": "Promesas grandes sin ancla concreta (nunca fallamos, somos los mejores, se lo garantizo todo) — la desconfianza regresa: eso me dijo el anterior.", "regla_id": "present.bala_generica"}, {"id": "pitch_prematuro", "severity": "major", "description": "Presenta antes de haber excavado y confirmado el dolor — recetó sin diagnóstico.", "regla_id": "discovery.receta_sin_diagnostico"}, {"id": "ignora_pistas", "severity": "major", "description": "Deja pasar la pista del dolor o los datos personales del cliente.", "regla_id": "discovery.escalera_capas"}, {"id": "si_capcioso", "severity": "minor", "description": "Preguntas de sí capciosas o huecas que incomodan.", "regla_id": "impulse.tren_del_si"}, {"id": "explica_sin_pintar", "severity": "major", "description": "Presentación de puros datos sin una sola escena.", "regla_id": "present.pintar_imagenes", "severity_fix": "minor->major (BOSS no baja errores de su paso)"}, {"id": "monologo", "severity": "minor", "description": "Bloques largos que atropellan al desconfiado.", "regla_id": "monologo"}], "success_criteria": [{"id": "discovery.dolor_real", "weight": 0.2, "description": "Excava el dolor por capas hasta la revelación completa y lo confirma verbalmente antes de presentar — la presentación no arranca sin diagnóstico terminado.", "regla_id": "discovery.confirmacion_con_sus_palabras"}, {"id": "presentation.conectar_dolor", "weight": 0.2, "description": "La presentación abre nombrando el dolor confirmado con las palabras del cliente y toda la oferta se articula como solución de ESE problema.", "regla_id": "present.dos_mitades"}, {"id": "presentation.pintar_imagenes", "weight": 0.15, "description": "Al menos una escena concreta del negocio del cliente con el problema resuelto, que el cliente recibe entrando en ella.", "regla_id": "present.pintar_imagenes"}, {"id": "presentation.tren_si_si", "weight": 0.15, "description": "Al menos dos preguntas de sí genuino ancladas en lo declarado, respondidas afirmativamente con comodidad.", "regla_id": "impulse.tren_del_si"}, {"id": "presentation.valor_personalizado", "weight": 0.15, "description": "Cero frases de catálogo genérico y cero promesas grandilocuentes sin ancla — todo el valor está personalizado y es creíble para un desconfiado.", "regla_id": "present.beneficio_no_caracteristica"}, {"id": "relationship.cpr", "weight": 0.15, "description": "Toca al menos un tema personal FORMD con genuinidad en el momento natural — y el escepticismo del cliente baja un escalón visible.", "regla_id": "relationship.cpr"}]}'::jsonb WHERE id = '4.16';
UPDATE public.nodes SET practice_script = '{"notes": "v2.0.0 Nodo nuevo. El espejo usa la pregunta que el vendedor promedio teme (y eso a mi de que me sirve?) como consecuencia automatica de no traducir. Ensena sin regano.", "scope": {"skills_in_focus": ["presentation.beneficio_no_caracteristica"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 10, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Fijate en que nunca dejo una caracteristica sola. Digo lo que el producto es, y en la misma frase digo que gana el con eso.\n\nLa caracteristica es mi lenguaje; el beneficio es el suyo. Si solo hablo el mio, me escucha sin entender.", "first_message": "Este maneja una formulacion mas estable a temperatura alta. Que significa para usted: le dura mas antes del siguiente cambio, o sea menos servicios al ano por unidad y menos gente reclamandole.\n\nY como le dura mas, su cliente regresa contento en lugar de regresar a quejarse."}, "you_do": {"prompt": "Eres el dueno de un negocio, atento y de buena disposicion, escuchando lo que el vendedor te presenta. Ya platicaron antes y ya le contaste que tu problema es que pierdes ventas cuando te falta producto. TU REGLA PRINCIPAL: reaccionas segun el vendedor traduzca o no. Si menciona una CARACTERISTICA sin traducirla a un beneficio concreto (una especificacion tecnica, un dato del producto, una certificacion, una marca), respondes con desinteres educado y le devuelves la pregunta que el vendedor promedio teme: y eso a mi de que me sirve? / ajam, y eso que me ayuda? / si, y? SI la traduce a algo concreto que tu ganas (dinero, mas clientes, menos problemas, tiempo, tranquilidad), te enganchas: asientes, preguntas mas al respecto, y conectas con tu propia situacion. Si te tira MUCHAS caracteristicas juntas sin traducir ninguna, te saturas y dices que lo tienes que pensar. NUNCA traduzcas tu por el: si el no dice el beneficio, tu no lo adivinas. Responde en 1 o 2 frases. TIPO DE CLIENTE: adopta el tipo de cliente que describa el contexto de la empresa (si revende, si consume para su propia operacion, o si distribuye) y responde SIEMPRE de forma coherente con ese tipo. Si eres un cliente que CONSUME y no revende, nunca hables de tus clientes ni de lo que se te vende: habla de lo que usas, de cuantas unidades manejas y de cada cuanto repones.", "objective": "El vendedor traduce cada caracteristica que menciona a un beneficio concreto para ese cliente: dinero, clientes, tiempo o tranquilidad. El scope se cubre cuando el cliente se engancha con al menos dos beneficios traducidos y conecta con su propia situacion."}, "closing": {"message": "Eso es traducir. Dijiste lo que el producto es y en la misma frase lo que el gana. La caracteristica es tu idioma; el beneficio es el suyo. El que solo habla el propio, presenta para si mismo. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como presentas. Vamos al desglose y te digo cuales se quedaron sin traducir."}}, "version": "2.0.0", "i_do_type": "demo", "failure_criteria": [{"id": "caracteristica_sin_traducir", "severity": "major", "description": "Menciona especificaciones, datos tecnicos o certificaciones sin decir que gana el cliente con eso. El cliente escucha sin entender y contesta y eso a mi de que me sirve.", "regla_id": "present.caracteristica_sin_traducir"}, {"id": "catalogo", "severity": "major", "description": "Encadena varias caracteristicas seguidas sin traducir ninguna. El cliente se satura y se defiende con un lo voy a pensar.", "regla_id": "present.caracteristica_sin_traducir"}, {"id": "beneficio_generico", "severity": "minor", "description": "Traduce a un beneficio que serviria para cualquier negocio (es de calidad, le va a gustar) en lugar de conectarlo con la situacion concreta del cliente.", "regla_id": "present.caracteristica_sin_traducir", "severity_override": {"default": "major", "razon": "incidental: fuera del foco del nodo"}}, {"id": "promesa_falsa", "severity": "critical", "description": "Inventa un beneficio que el producto no da, o exagera un resultado para que suene mejor. El valor se construye con verdad.", "regla_id": "present.bala_generica", "severity_override": {"default": "major", "razon": "escalada: habilidad espejo del nodo"}}], "success_criteria": [{"id": "presentation.beneficio_no_caracteristica", "weight": 1, "description": "Cada caracteristica que menciona va acompanada de su traduccion a algo concreto que el cliente gana: mas dinero, mas clientes, menos tiempo perdido o menos problemas. La traduccion debe ser especifica de ESE negocio, no generica. Mencionar la caracteristica sola no cumple, aunque sea impresionante.", "regla_id": "present.beneficio_no_caracteristica"}]}'::jsonb WHERE id = '4.2';